import math
import pytest

def sim_pearson(prefs, person1, person2):
    shared_items = {}
    for item in prefs[person1]:
        if item in prefs[person2]:
            shared_items[item] = 1

    n = len(shared_items)

    if n == 0:
        return 0

    sum1 = sum([prefs[person1][item] for item in shared_items])
    sum2 = sum([prefs[person2][item] for item in shared_items])

    sum1_sq = sum([pow(prefs[person1][item], 2) for item in shared_items])
    sum2_sq = sum([pow(prefs[person2][item], 2) for item in shared_items])

    product_sum = sum([prefs[person1][item] * prefs[person2][item]
                      for item in shared_items])

    num = product_sum - (sum1 * sum2 / n)
    den = math.sqrt((sum1_sq - pow(sum1, 2) / n) *
                    (sum2_sq - pow(sum2, 2) / n))
    if den == 0:
        return 0
    return num / den

# Test cases
@pytest.mark.parametrize("prefs, person1, person2, expected", [
    (
        {
            "Alice": {"Item1": 3.5, "Item2": 4.0},
            "Bob": {"Item1": 3.5, "Item2": 4.0}
        },
        "Alice",
        "Bob",
        1.0
    ),
    (
        {
            "Alice": {"Item1": 3.5, "Item2": 4.0},
            "Bob": {"Item1": 2.0, "Item2": 3.0}
        },
        "Alice",
        "Bob",
        0.8660254037844386
    ),
    (
        {
            "Alice": {"Item1": 3.5, "Item2": 4.0},
            "Bob": {"Item1": 2.0, "Item2": 3.0}
        },
        "Bob",
        "Alice",
        0.8660254037844386
    ),
    (
        {
            "Alice": {"Item1": 3.5, "Item2": 4.0},
            "Bob": {"Item3": 2.0, "Item4": 3.0}
        },
        "Alice",
        "Bob",
        0.0
    ),
    (
        {},
        "Alice",
        "Bob",
        0.0
    )
])

def test_sim_pearson(prefs, person1, person2, expected):
    assert abs(sim_pearson(prefs, person1, person2) - expected) < 1e-9

